import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { openDatabase, toJob, type Job, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

/** The worker counts as up if its heartbeat is at most this old. */
const HEARTBEAT_MAX_AGE_MS = 3_000;
const MAX_BODY_BYTES = 64 * 1024;
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
const PAYLOAD_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

const selectJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const selectJob = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, idempotency_key, next_run_at, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
);
const selectHeartbeat = db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'");

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', `Invalid request: ${fields.map((f) => f.field).join(', ')}.`, fields);
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendError(res, 405, 'method_not_allowed', 'Method not allowed for this path.', undefined);
  res.setHeader('allow', allow);
}

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function checkInt(value: unknown, fallback: number, min: number, max: number, field: string, errors: FieldError[]): number {
  if (value === undefined) return fallback;
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    errors.push({ field, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return value;
}

/** Validates the parsed body; pushes every problem onto `errors` and returns the payload only when valid. */
function validatePayload(body: unknown, errors: FieldError[]): Payload | undefined {
  if (!isObject(body)) {
    errors.push({ field: 'body', message: 'body must be a JSON object' });
    return undefined;
  }
  const before = errors.length;
  for (const field of Object.keys(body)) {
    if (!PAYLOAD_FIELDS.has(field)) errors.push({ field, message: 'unknown field' });
  }
  const input = body.input;
  if (typeof input !== 'string') {
    errors.push({ field: 'input', message: 'is required and must be a string' });
  } else if (input.length < 1 || input.length > 1000) {
    errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  } else if (input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be only whitespace' });
  }
  const steps = checkInt(body.steps, 5, 1, 20, 'steps', errors);
  const failAttempts = checkInt(body.failAttempts, 0, 0, 5, 'failAttempts', errors);
  if (typeof input !== 'string' || errors.length > before) return undefined;
  return { input, steps, failAttempts };
}

type CreateResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/** Creates a job, or returns the job already stored under the same idempotency key. */
function createJob(payload: Payload, key: string | undefined): CreateResult {
  db.exec('BEGIN IMMEDIATE');
  try {
    let result: CreateResult;
    const existing = key === undefined ? undefined : (selectByKey.get(key) as unknown as JobRow | undefined);
    if (existing) {
      const same =
        existing.input === payload.input && existing.steps === payload.steps && existing.fail_attempts === payload.failAttempts;
      result = same ? { kind: 'replayed', job: toJob(existing) } : { kind: 'conflict' };
    } else {
      const id = randomUUID();
      const now = new Date().toISOString();
      insertJob.run(id, payload.input, payload.steps, payload.failAttempts, key ?? null, now, now);
      result = { kind: 'created', job: toJob(selectJob.get(id) as unknown as JobRow) };
    }
    db.exec('COMMIT');
    return result;
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handlePost(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const mediaType = String(req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    return invalid(res, [{ field: 'body', message: 'Content-Type must be application/json' }]);
  }
  if (body === null) return invalid(res, [{ field: 'body', message: `body exceeds ${MAX_BODY_BYTES} bytes` }]);

  let parsed: unknown;
  try {
    parsed = JSON.parse(body);
  } catch {
    return invalid(res, [{ field: 'body', message: 'body is not valid JSON' }]);
  }

  const errors: FieldError[] = [];
  const payload = validatePayload(parsed, errors);
  const key = req.headers['idempotency-key'];
  if (key !== undefined && (typeof key !== 'string' || !IDEMPOTENCY_KEY_RE.test(key))) {
    errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }
  if (!payload || errors.length > 0) return invalid(res, errors);

  const result = createJob(payload, typeof key === 'string' ? key : undefined);
  if (result.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.kind === 'created' ? 201 : 200, result.job);
}

function handleGet(res: ServerResponse, id: string | undefined): void {
  if (id === undefined) {
    const jobs = (selectJobs.all() as unknown as JobRow[]).map(toJob);
    return send(res, 200, { jobs });
  }
  const row = selectJob.get(id) as unknown as JobRow | undefined;
  if (!row) return sendError(res, 404, 'not_found', 'No job with that id.');
  send(res, 200, toJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = selectHeartbeat.get() as unknown as { at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.at <= HEARTBEAT_MAX_AGE_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    return method === 'GET' ? handleHealth(res) : methodNotAllowed(res, 'GET');
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return handleGet(res, undefined);
    if (method === 'POST') return handlePost(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (jobMatch) {
    return method === 'GET' ? handleGet(res, jobMatch[1]) : methodNotAllowed(res, 'GET');
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error(e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeIdleConnections();
  setTimeout(() => server.closeAllConnections(), 500).unref();
  setTimeout(() => process.exit(0), 3_000).unref();
}
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, shutdown);

